//! pbrt-v4's unit tests, one module per source file (`filters_test.cpp`),
//! each test naming the `TEST(Suite, Name)` it ports; and the values pbrt-v4
//! computes on fixed inputs (`known_values.rs`, generated by
//! `known_values.cpp`), checked by the `known_values` tests.

mod cameras;
mod filters_test;
mod known_values;
mod sensor;

/// Asserts that each of `actual` is within `max_ulps` of the float whose
/// bits are the matching entry of `expected`.
///
/// pbrt-v4's library is built with `-march=native` in GNU C++ mode, which
/// lets its compiler fuse multiplies and adds, and its transcendentals come
/// from the libm it was built with; Umbra fuses nothing implicitly and takes
/// its transcendentals from its own kernels or glibc (ADR 0022). Results can
/// differ in their last bits.
#[track_caller]
pub(crate) fn assert_ulps<const N: usize>(
    actual: [f32; N],
    expected: [u32; N],
    max_ulps: u32,
    what: &str,
) {
    let distance = actual
        .into_iter()
        .zip(expected.map(f32::from_bits))
        .map(|(a, e)| ulps(a, e))
        .max()
        .unwrap_or(0);
    assert!(
        distance <= max_ulps,
        "{what}: {actual:?} vs pbrt-v4's {:?}, {distance} ulps apart",
        expected.map(f32::from_bits)
    );
}

/// Asserts that each of `actual` is within `max_ulps` ulps, of the largest
/// expected magnitude, of the float whose bits are the matching entry of
/// `expected`: the error of a vector's components relative to its length.
/// A component near zero that comes out of a cancellation is close in this
/// sense but can be many of its own ulps away.
#[track_caller]
pub(crate) fn assert_scaled_ulps<const N: usize>(
    actual: [f32; N],
    expected: [u32; N],
    max_ulps: u16,
    what: &str,
) {
    let expected = expected.map(f32::from_bits);
    let scale = expected
        .iter()
        .fold(f32::MIN_POSITIVE, |m, e| m.max(e.abs()));
    let ulp = f32::from_bits(scale.to_bits() + 1) - scale;
    let error = actual
        .into_iter()
        .zip(expected)
        .map(|(a, e)| (a - e).abs())
        .fold(0.0, f32::max);
    assert!(
        error <= ulp * f32::from(max_ulps),
        "{what}: {actual:?} vs pbrt-v4's {expected:?}, {} ulps of {scale} apart",
        error / ulp
    );
}

/// The number of floats between `a` and `b`, with ±0 equal; `u32::MAX`
/// if either is NaN, unless both are.
fn ulps(a: f32, b: f32) -> u32 {
    if a.is_nan() || b.is_nan() {
        return if a.is_nan() && b.is_nan() {
            0
        } else {
            u32::MAX
        };
    }
    let ordered = |f: f32| {
        let bits = i64::from(f.to_bits().cast_signed());
        if bits < 0 {
            i64::from(i32::MIN) - bits
        } else {
            bits
        }
    };
    u32::try_from((ordered(a) - ordered(b)).unsigned_abs()).unwrap_or(u32::MAX)
}

/// The floats whose bits are `bits`.
pub(crate) fn floats<const N: usize>(bits: [u32; N]) -> [f32; N] {
    bits.map(f32::from_bits)
}
